from urllib.parse import urlparse, parse_qs, unquote

def parse_query_string(query):
    """
    Parse a URL query string into a dict mapping each key to a list of decoded values.
    Ignore a leading ?. Use urllib.parse semantics for percent decoding and blank values.
    """
    if not query:
        return {}

    # Remove leading '?' if present
    if query.startswith('?'):
        query = query[1:]

    if not query:
        return {}

    # parse_qs handles percent decoding and returns a dict mapping keys to lists of values.
    # It correctly handles empty values (e.g., "a=&b" -> {'a': [''], 'b': ['']})
    # and multiple values for the same key (e.g., "a=1&a=2" -> {'a': ['1', '2']}).
    parsed_qs = parse_qs(query)

    # parse_qs already uses unquote semantics internally, which matches the requirement.
    return parsed_qs

