def parse_semver(value):
    """
    Parse a semantic version string MAJOR.MINOR.PATCH with an optional leading v.
    Return a tuple of three integers. Reject missing parts, non-integers, or negative numbers with ValueError.
    """
    if not isinstance(value, str):
        raise ValueError("Input must be a string.")

    # Remove optional leading 'v'
    version_str = value
    if version_str.startswith('v'):
        version_str = version_str[1:]

    parts = version_str.split('.')

    if len(parts) != 3:
        raise ValueError("Semantic version must have MAJOR.MINOR.PATCH format.")

    try:
        major = int(parts[0])
        minor = int(parts[1])
        patch = int(parts[2])
    except ValueError:
        # This catches cases where parts[i] cannot be converted to int (e.g., "1.a.2")
        raise ValueError("All version components must be integers.")

    # Check for negative numbers
    if major < 0 or minor < 0 or patch < 0:
        raise ValueError("Version components cannot be negative.")

    return (major, minor, patch)

