def histogram_bins(values, bin_size):
    if bin_size <= 0:
        raise ValueError("bin_size must be greater than 0")

    counts = {}
    for value in values:
        # Calculate the bin start. Integer division by bin_size gives the index,
        # and multiplying by bin_size gives the start of the bin.
        # For bin_size 10:
        # 0..9 -> 0 // 10 * 10 = 0
        # 10..19 -> 10 // 10 * 10 = 10
        # -1..8 -> -1 // 10 * 10 = -10 (Python's floor division handles negatives correctly)
        bin_start = (value // bin_size) * bin_size

        if bin_start in counts:
            counts[bin_start] += 1
        else:
            counts[bin_start] = 1

    return counts

