def has_cycle_directed(graph):
    """
    Checks if a directed graph has a cycle.

    The graph is represented as a dictionary where keys are nodes and values 
    are lists of neighbors (outgoing edges).
    """

    # State tracking for DFS
    # 0: unvisited (white)
    # 1: visiting (gray - currently in the recursion stack)
    # 2: visited (black - finished processing)
    state = {node: 0 for node in graph}

    # Ensure all nodes mentioned as neighbors are also in the state map, 
    # even if they have no outgoing edges listed in the input graph keys.
    for neighbors in graph.values():
        for neighbor in neighbors:
            if neighbor not in state:
                state[neighbor] = 0

    def dfs(node):
        # Mark current node as visiting (gray)
        state[node] = 1

        # Explore neighbors
        if node in graph:
            for neighbor in graph[node]:
                if state.get(neighbor) == 1:
                    # Found a back edge to a node currently in the recursion stack (gray)
                    return True

                if state.get(neighbor) == 0:
                    # Unvisited, recurse
                    if dfs(neighbor):
                        return True

        # Finished processing this node and all its descendants (black)
        state[node] = 2
        return False

    # Iterate over all nodes to handle disconnected components
    for node in state:
        if state[node] == 0:
            if dfs(node):
                return True

    return False

