def reverse_adjacency(graph):
    """
    Reverses the adjacency list representation of a graph.

    Args:
        graph: A dictionary where keys are nodes and values are lists of neighbors (outgoing edges).

    Returns:
        A dictionary where each node maps to the sorted list of incoming neighbors.
        Includes nodes that only appear as neighbors.
    """
    reversed_graph = {}

    # 1. Initialize all nodes (both sources and destinations) in the reversed graph
    all_nodes = set(graph.keys())
    for neighbors in graph.values():
        all_nodes.update(neighbors)

    for node in all_nodes:
        reversed_graph[node] = []

    # 2. Populate the reversed edges
    for u, neighbors in graph.items():
        for v in neighbors:
            # Edge u -> v in original graph means v -> u in reversed graph
            if v in reversed_graph:
                reversed_graph[v].append(u)
            # This case should ideally not happen if initialization was correct, 
            # but it's safe to handle.
            else:
                reversed_graph[v] = [u]

    # 3. Sort the lists of incoming neighbors
    for node in reversed_graph:
        reversed_graph[node].sort()

    return reversed_graph

