def validate_parentheses(text):
    stack = []
    mapping = {")": "(", "]": "[", "}": "{"}
    opening_brackets = set("([{")
    closing_brackets = set(")]}")

    for char in text:
        if char in opening_brackets:
            stack.append(char)
        elif char in closing_brackets:
            if not stack:
                return False
            top_element = stack.pop()
            if mapping[char] != top_element:
                return False
        # Ignore other characters

    return not stack

