def run_length_encode(items):
    if not items:
        return []

    encoded_list = []
    current_value = items[0]
    current_count = 0

    for item in items:
        if item == current_value:
            current_count += 1
        else:
            encoded_list.append((current_value, current_count))
            current_value = item
            current_count = 1

    # Append the last sequence
    encoded_list.append((current_value, current_count))
    return encoded_list

